import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  Input,
} from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  CustomTextArea,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import makeAnimated from "react-select/animated";
import retailerReceiptsApi from "../../../api/retailers/retailerReceiptsApi";
import productsApi from "../../../api/productsApi";
import entitiesApi from "../../../api/entitiesApi";
import discountsApi from "../../../api/discountsApi";
import dayjs from "dayjs";
import "dayjs/locale/en-gb";
import { Modal } from "antd";
import logisticsApi from "../../../api/logistics/logisticsApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import servicesApi from "../../../api/servicesApi";

export default function LaboratoryServicesFormModal({
  ismodalOpen,
  setisModalOpen,
  selectedLaboratoryService,
  modalTitle = "Add new retail inventory",
  updated,
  setUpdated,
}) {
  const moment = require("moment");
  const { currentColor } = useStateContext()


  const [errors, setErrors] = useState();




  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);
  const laboratoryServiceApi = useApi(servicesApi.servicesAdminAction)
  const createLaboratoryService = async (data) => {

    await laboratoryServiceApi.request(data)
  }


  useEffect(() => {
    if (laboratoryServiceApi.data) {
      if (laboratoryServiceApi.data.laboratory_service) {
        toast.success(laboratoryServiceApi.data.response_message)
      }


      if (laboratoryServiceApi.data.errors) {
        setErrors(laboratoryServiceApi.data.errors)
      }
    }
  }, [laboratoryServiceApi.data])

  const formik = useFormik({
    initialValues: {

      title: selectedLaboratoryService ? selectedLaboratoryService.title : "",
      time_to_result: selectedLaboratoryService ? selectedLaboratoryService.time_to_result : "",
      sample: selectedLaboratoryService ? selectedLaboratoryService.sample : "",
      sample_handling_temparature: selectedLaboratoryService ? { label: selectedLaboratoryService.sample_handling_temparature, value: selectedLaboratoryService.sample_handling_temparature } : "",
      time_to_result_unit: selectedLaboratoryService ? { label: selectedLaboratoryService.time_to_result_unit, value: selectedLaboratoryService.time_to_result_unit } : "",

    },

    validationSchema: Yup.object({
      title: Yup.string().required().label("Title"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      if (selectedLaboratoryService) {

      } else {
        const data = {
          "action": "CreateLaboratoryService",
          "title": values.title,
          "sample": values.sample,
          "sample_handling_temparature": values.sample_handling_temparature.value,
          "time_to_result_unit": values.time_to_result_unit.value,
          "time_to_result": values.time_to_result
        }
        createLaboratoryService(data)
      }


      // resetForm();
    },
  });




  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  return (
    <div className="w-full">
      <Modal
        width={600}
        className="w-full text-center"
        title={selectedLaboratoryService ? `EDIT ${selectedLaboratoryService.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <div className="w-full grid grid-cols-1 mt-5 gap-1 ">

            <CustomFormItem
              touched={formik.touched.title}
              error={formik.errors.title}
            >
              <CustomInput
                className="uppercase"
                required={true}
                label="Enter title"
                id="title"
                name="title"
                onChange={formik.handleChange}
                placeholder="Enter title"
                size="large"
                type="text"
                value={formik.values.title}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.sample}
              error={formik.errors.sample}
            >
              <CustomTextArea
                required={true}
                label="Enter sample description"
                id="sample"
                name="sample"
                onChange={formik.handleChange}
                placeholder="Enter sample description"
                size="large"
                type="text"
                value={formik.values.sample}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.sample_handling_temparature}
              error={formik.errors.sample_handling_temparature}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="sample_handling_temparature"
                id="sample_handling_temparature"
                label="Select sample handling temparature"
                size="large"
                onChange={(value) =>
                  formik.setFieldValue("sample_handling_temparature", value)
                }
                value={formik.values.sample_handling_temparature}
                placeholder="Select sample handling temparature"
                options={[
                  { label: "FROZEN", value: "FROZEN" },
                  { label: "REFRIGERATE", value: "REFRIGERATE" },
                  { label: "ROOM", value: "ROOM" },
                ]}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.time_to_result_unit}
              error={formik.errors.time_to_result_unit}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="time_to_result_unit"
                id="time_to_result_unit"
                label="Time to result unit"
                size="large"
                onChange={(value) =>
                  formik.setFieldValue("time_to_result_unit", value)
                }
                value={formik.values.time_to_result_unit}
                placeholder="Time to result unit"
                options={[
                  { label: "MINUTES", value: "MINUTES" },
                  { label: "HOURS", value: "HOURS" },
                  { label: "DAYS", value: "DAYS" },
                  { label: "WEEKS", value: "WEEKS" },
                ]}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.time_to_result}
              error={formik.errors.time_to_result}
            >
              <CustomInput
                required={true}
                label="Enter time to result"
                id="time_to_result"
                name="time_to_result"
                onChange={formik.handleChange}
                placeholder="Enter time to result"
                size="large"
                type="number"
                value={formik.values.time_to_result}
              />
            </CustomFormItem>













          </div>
          <div className="w-full items-center mt-2">
            <Button style={{ background: currentColor }} className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
