import React, { useEffect, useState } from "react";

import useApi from "../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import LaboratoryServicesFormModal from "./LaboratoryServicesFormModal";
import LaboratoryServicesTable from "./LaboratoryServicesTable";
import servicesApi from "../../../api/servicesApi";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Sample", uid: "sample" },
  { name: "Time to Result Unit", uid: "time_to_result_unit" },
  { name: "Time To result", uid: "time_to_result" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function LaboratoryServicesList() {
  const [ismodalOpen, setisModalOpen] = useState(false);
  const navigate = useNavigate();
  const [selectedLaboratoryService, setselectedLaboratoryService] = useState();
  const [laboratoryService, setlaboratoryservices] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);

  const getLaboratoryservicesApi = useApi(servicesApi.servicesAdminAction);
  const getLaboratoryservices = async () => {
    await getLaboratoryservicesApi.request({
      "action": "GetLaboratoryServices"
    })
  }

  useEffect(() => {
    getLaboratoryservices();
  }, [])


  const handleEditAction = (item) => {
    setisModalOpen(true);
    setselectedLaboratoryService(item);
    setmodalTitle(`Edit ${item.title}`);
  };

  const handleAddAction = () => {
    setisModalOpen(true);
    setmodalTitle("Add new laboratory service");
    setselectedLaboratoryService(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (getLaboratoryservicesApi.data && getLaboratoryservicesApi.data.length) {
      setlaboratoryservices(getLaboratoryservicesApi.data);
    }
    console.log("getDepartmentsActionsApi.data", getLaboratoryservicesApi.data);
  }, [getLaboratoryservicesApi.data]);



  //Filtering data
  useEffect(() => {
    setdata(laboratoryService);
  }, [laboratoryService]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      laboratoryService &&
      laboratoryService.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        laboratoryService.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(laboratoryService);
    }
  };

  return <div className="mt-16 md:mt-2">
    {ismodalOpen && (
          <LaboratoryServicesFormModal
        ismodalOpen={ismodalOpen}
        setisModalOpen={setisModalOpen}
        selectedLaboratoryService={selectedLaboratoryService}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}

        <LaboratoryServicesTable
      title={"Pathology services"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>

}

export default LaboratoryServicesList;
